interface Sender { fun send(msg: String): Boolean; fun close() }

class RetryingSender(
    private val delegate: Sender,          // wrapped component
    private val attempts: Int,
) : Sender by delegate {                   // every other member is generated + forwarded
    override fun send(msg: String): Boolean {   // only the changed member is written
        repeat(attempts - 1) { if (delegate.send(msg)) return true }
        return delegate.send(msg)
    }
}
